const email = $input.first().json;
const body = email.text || email.snippet || '';
const subject = email.subject || '';
const from = email.from || '';

// Extraire les données du formulaire
const nameMatch = body.match(/[Nn]om[\s:]+([^\n]+)/i);
const hotelMatch = body.match(/[Hh]ôtel[\s:]+([^\n]+)/i) || body.match(/[Hh]otel[\s:]+([^\n]+)/i);
const roomsMatch = body.match(/[Cc]hambres?[\s:]+([\d]+)/i) || body.match(/rooms?[\s:]+([\d]+)/i);
const msgMatch = body.match(/[Mm]essage[\s:]+([\s\S]+)/i);

return [{
  json: {
    email_from: from,
    email_subject: subject,
    email_body: body,
    prospect_name: nameMatch ? nameMatch[1].trim() : 'Inconnu',
    hotel_name: hotelMatch ? hotelMatch[1].trim() : 'Non précisé',
    rooms_count: roomsMatch ? parseInt(roomsMatch[1]) : 0,
    message: msgMatch ? msgMatch[1].trim() : body.substring(0, 500),
    timestamp: new Date().toISOString()
  }
}];

const aiResponse = $input.first().json;
const content = aiResponse.choices[0].message.content;

let parsed;
try {
  const jsonMatch = content.match(/\{[\s\S]+\}/);
  parsed = JSON.parse(jsonMatch[0]);
} catch(e) {
  parsed = {
    temperature: 'TIÈDE',
    reason: 'Erreur de parsing',
    response: 'Merci de votre message. Elton Skenderaj vous contactera sous 24h pour un audit gratuit. AHRPA'
  };
}

const prev = $('Extraire données').first().json;
return [{ json: { ...prev, ...parsed } }];
